function createState(initialValue) {
  var state = initialValue;
  function getValue() { return state; }
  function setValue(newValue) { state = newValue; }
  return [getValue, setValue];
}

function createEffect(effect, deps) {
  var prevDeps = null;
  var cleanup = null;
  return function runEffect() {
    var depsChanged = prevDeps === null || JSON.stringify(prevDeps) !== JSON.stringify(deps);
    if (depsChanged) {
      if (typeof cleanup === 'function') cleanup();
      cleanup = effect();
      prevDeps = deps.slice();
    }
  };
}

function useDebounce(fn, delay) {
  var timer = null;
  return function() {
    var args = arguments;
    clearTimeout(timer);
    timer = setTimeout(function() {
      fn.apply(null, args);
    }, delay);
  };
}

function createRouter(routes) {
  return function navigate(path) {
    for (var pattern in routes) {
      var params = matchRoute(pattern, path);
      if (params !== null) return routes[pattern](params);
    }
    return null;
  };
}
function matchRoute(pattern, path) {
  var pp = pattern.split('/'), pa = path.split('/');
  if (pp.length !== pa.length) return null;
  var params = {};
  for (var i = 0; i < pp.length; i++) {
    if (pp[i].startsWith(':')) params[pp[i].slice(1)] = pa[i];
    else if (pp[i] !== pa[i]) return null;
  }
  return params;
}
